-- Hapus transaksi tahun buku 2025 supaya database hanya berisi data 2026, tetapi Neraca 2025
-- (isian dan rincian, Laba 2025 dari 042) tetap, untuk kolom 31 Desember 2025 dan saldo awal.
-- Sama seperti 039_hapus_data_2025 (yang sudah dikembalikan dengan 043_reinsert_data_2025).
-- Yang dihapus (hard delete, bukan reversal):
--   * semua transaksi bertanggal sebelum 01-01-2026 (Buku Kas 2025, mutasi simpanan dan
--     pinjaman 2025, saldo awal Kas 31-12-2024, koreksi saldo 2025 dari script 019/027/032/033)
--     beserta komponen dan reversal-nya;
--   * transaksi 01-01-2026 yang hanya berisi saldo awal (saldo awal 2026 dari impor 2026 yang
--     sudah dibalik impor 2025, pembaliknya, dan tunggakan/lebih bayar awal 2026);
--   * pinjaman dan anggota yang hanya punya transaksi 2025;
-- Sebagai gantinya dicatat saldo awal 2026 yang dihitung dari data yang dihapus, sehingga
-- saldo simpanan, saldo pinjaman, tunggakan pokok/bunga per bulan 2026 dan saldo awal Buku Kas
-- 2026 sama persis seperti sebelum skrip ini:
--   * satu transaksi saldo awal simpanan per anggota (01-01-2026, NON_KAS);
--   * satu transaksi saldo awal pinjaman per pinjaman (01-01-2026, NON_KAS): pokok, tunggakan
--     atau lebih bayar pokok dan bunga;
--   * saldo Kas Fisik 31-12-2025 (KAS, bertanggal 31-12-2025 agar menjadi saldo awal Buku Kas 2026).
-- Tidak diubah: parameter (tarif insentif berlaku sejak 2025 masih dipakai 2026), audit_events,
-- saldo awal Kas Buku Tabungan 2026, transaksi 01-01-2026 yang bukan saldo awal.
-- Data yang dihapus bisa dikembalikan dengan notes/_bisa-dihapus/data-scripts/043_reinsert_data_2025.sql
-- dari backup database sebelum skrip ini.
--
-- Dibuat dari backup: notes/_bisa-dihapus/backup-db/koperasi-sebelum-043.db
-- Gagal tanpa mengubah apa pun kalau data 2025 di database berbeda dari backup itu (jumlah dan
-- nilai transaksi yang akan dihapus, atau syarat pinjaman yang saldo awalnya dihitung).
-- Database tanpa data 2025 (instalasi baru, e2e) tidak diubah.

CREATE TEMP TABLE hapus043_tx (id TEXT PRIMARY KEY);
SELECT t.id FROM transactions t
WHERE t.company_id = 'default' AND t.reversed_transaction_id IS NULL
  AND (
    t.business_date < '2026-01-01'
    OR (
      t.business_date = '2026-01-01'
      AND EXISTS (SELECT 1 FROM transaction_components c WHERE c.transaction_id = t.id)
      AND NOT EXISTS (
        SELECT 1 FROM transaction_components c
        WHERE c.transaction_id = t.id AND c.component_type NOT IN ('LOAN_OPENING','LOAN_OPENING_ARREARS_PRINCIPAL','LOAN_OPENING_PREPAID_PRINCIPAL','LOAN_OPENING_ARREARS_INTEREST','LOAN_OPENING_PREPAID_INTEREST','SAVINGS_OPENING')
      )
    )
  );
SELECT r.id FROM transactions r
WHERE r.company_id = 'default' AND r.reversed_transaction_id IN (SELECT id FROM hapus043_tx);

CREATE TEMP TABLE hapus043_guard (state TEXT NOT NULL CHECK (state IN ('kosong', 'cocok')));
SELECT CASE
  WHEN NOT EXISTS (SELECT 1 FROM hapus043_tx) THEN 'kosong'
  WHEN (SELECT
    (SELECT COUNT(*) || '/' || SUM(amount) FROM transactions WHERE id IN (SELECT id FROM hapus043_tx))
    || '|' ||
    (SELECT COUNT(*) || '/' || SUM(amount) FROM transaction_components WHERE transaction_id IN (SELECT id FROM hapus043_tx))
    || '|' ||
    (SELECT COUNT(*) FROM transactions r WHERE r.reversed_transaction_id IN (SELECT id FROM hapus043_tx) AND r.id NOT IN (SELECT id FROM hapus043_tx))) = '3664/11771451772|5722/11771451772|0'
   AND (SELECT COUNT(*) || '/' || SUM(plafond) || '/' || SUM(tenor) || '/' || SUM(CAST(ROUND(rate_annual*1000) AS INTEGER)) || '/' || group_concat(interest_type || COALESCE(loan_type,'-') || due_date, ',') FROM (SELECT * FROM loans WHERE id IN ('default-L014','default-L015','default-L017','default-L018','default-L025','default-L032','default-L037','default-L040','default-L043','default-L044','default-L045','default-L046','default-L047','default-L052','default-L056','default-L060','default-L061','default-L063','default-L064','default-L070','default-L071','default-L075','default-L076','default-L085','default-L089','default-L092','default-L094','default-L095','default-L098','default-L099','default-L100','default-L101','default-L102','default-L104','default-L106','default-L108','default-L109','default-L110','default-L111','default-L112','default-L113','default-L114','default-L115','default-L116','default-L117','default-L118','default-L119','default-L122','default-L123','default-L124','default-L125','default-L126','default-L128','default-L129','default-L130','default-L131','default-L134','default-L136','default-L139','default-L140','default-L141','default-L142','default-L143','default-L144','default-L145','default-L146','default-L147','default-L148','default-L149','default-L151','default-L152','default-L154','default-L155','default-L158','default-L159','default-L160','default-L161','default-L162','default-L171','default-L176','default-L178','default-L179','default-L180','default-L181','default-L182','default-L183','default-L184','default-L185','default-L186','default-L187','default-L188','default-L189','default-L190','default-L191','default-L192','default-L193','default-L194','default-L195','default-L196','default-L197','default-L198','default-L199','default-L200','default-L201','default-L202','default-L203','default-L204','default-L205','default-L206','default-L207','default-L208','default-L209','default-L210','default-L211','default-L212','default-L213','default-L214','default-L215','default-L216','default-L217','default-L218','default-L219','default-L220','default-L221','default-L222','default-L223','default-L224','default-L226','default-L227','default-L228','default-L229','default-L230','default-L231','default-L232','default-L233','default-L234','default-L239','default-L241') ORDER BY id)) = '138/1373217000/2190/3251000/MenurunBulanan2027-11-25,MenurunBulanan2026-11-05,PlatBulanan2027-09-16,MenurunBulanan2027-09-18,MenurunBulanan2027-08-27,MenurunBulanan2027-11-20,PlatBulanan2026-09-02,PlatBulanan2016-11-05,PlatBulanan2027-05-17,PlatSementara2021-11-25,PlatSementara2021-11-14,PlatBulanan2022-11-04,MenurunBulanan2025-08-11,MenurunBulanan2027-04-05,MenurunBulanan2027-10-15,MenurunBulanan2025-12-10,PlatBulanan2029-10-31,PlatSementara2026-09-22,PlatSementara2026-11-18,MenurunSementara2022-08-25,PlatBulanan2029-10-31,PlatSementara2026-12-02,MenurunBulanan2024-05-17,MenurunBulanan2027-07-16,MenurunBulanan2027-02-18,MenurunBulanan2027-01-02,MenurunBulanan2027-07-08,MenurunBulanan2026-06-11,MenurunBulanan2026-05-16,PlatSementara2026-01-10,MenurunBulanan2027-06-17,PlatSementara2026-03-25,MenurunBulanan2027-05-02,MenurunBulanan2028-12-15,MenurunBulanan2027-06-01,MenurunBulanan2027-02-17,MenurunBulanan2027-04-04,PlatSementara2025-12-22,MenurunBulanan2026-10-23,PlatSementara2026-01-25,MenurunBulanan2027-01-21,PlatSementara2026-01-25,MenurunBulanan2027-01-22,MenurunBulanan2026-04-11,MenurunBulanan2026-01-05,MenurunBulanan2026-07-09,MenurunBulanan2027-06-13,MenurunBulanan2026-10-01,MenurunBulanan2026-03-14,MenurunBulanan2027-02-13,PlatSementara2026-01-25,MenurunBulanan2027-04-30,MenurunBulanan2026-06-01,MenurunBulanan2027-08-19,MenurunBulanan2027-08-19,MenurunBulanan2027-12-10,MenurunBulanan2026-08-06,MenurunBulanan2027-04-12,PlatBulanan2027-09-23,PlatSementara2026-01-25,MenurunBulanan2026-04-28,MenurunBulanan2029-10-14,PlatBulanan2027-07-10,MenurunBulanan2027-03-01,MenurunBulanan2026-05-22,MenurunBulanan2027-12-06,PlatBulanan2027-08-17,MenurunBulanan2027-02-18,PlatBulanan2026-06-05,MenurunBulanan2027-11-26,MenurunBulanan2026-05-16,MenurunBulanan2027-12-02,MenurunBulanan2027-03-08,MenurunBulanan2026-07-03,MenurunSementara2026-02-16,MenurunBulanan2026-03-21,MenurunBulanan2027-03-14,MenurunBulanan2026-05-30,MenurunBulanan2027-03-09,MenurunBulanan2027-02-16,MenurunBulanan2027-03-06,Plat-2026-07-28,Menurun-2026-09-30,Plat-2025-08-25,Plat-2025-12-05,Plat-2026-05-23,Plat-2026-05-05,Plat-2026-05-11,Plat-2025-12-16,Plat-2024-10-27,Plat-2023-05-19,Plat-2025-12-09,Plat-2024-10-30,Plat-2025-04-06,Plat-2025-09-21,Plat-2023-08-18,Plat-2024-11-07,Plat-2024-12-05,Plat-2024-12-07,Plat-2024-10-26,Plat-2025-06-17,Plat-2025-02-18,Plat-2024-07-11,Plat-2020-07-13,Plat-2024-05-26,Plat-2025-08-12,Plat-2024-04-10,Plat-2025-09-04,Plat-2025-12-13,Plat-2025-04-27,Plat-2020-07-09,Plat-2019-09-08,Plat-2024-12-22,Plat-2026-11-03,Plat-2025-11-05,Plat-2025-01-24,Plat-2024-09-22,Plat-2020-07-06,Plat-2025-12-13,Plat-2026-07-12,Plat-2026-06-01,Plat-2026-10-13,Plat-2025-10-09,Plat-2026-07-08,Plat-2024-03-29,Plat-2020-10-31,Plat-2024-12-05,Plat-2026-08-12,Plat-2026-01-03,Plat-2025-08-14,Plat-2026-02-10,Plat-2025-02-18,Plat-2025-12-13,Plat-2024-09-01,Plat-2026-04-26,Plat-2026-03-03,Menurun-2025-06-06,Menurun-2026-06-01' THEN 'cocok'
  ELSE 'beda'
END;

-- Trigger append-only dilepas selama penghapusan, lalu dibuat ulang persis seperti semula.
DROP TRIGGER components_append_only_delete;
DROP TRIGGER components_append_only_update;
DROP TRIGGER transaction_groups_append_only_delete;
DROP TRIGGER transaction_groups_append_only_update;
DROP TRIGGER transactions_append_only_delete;
DROP TRIGGER transactions_append_only_update;

DELETE FROM transaction_groups WHERE transaction_id IN (SELECT id FROM hapus043_tx) AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');
DELETE FROM transaction_components WHERE transaction_id IN (SELECT id FROM hapus043_tx) AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');
DELETE FROM transactions WHERE id IN (SELECT id FROM hapus043_tx) AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');

DELETE FROM loans WHERE company_id = 'default' AND id IN ('default-L225','default-L235','default-L236','default-L237','default-L238','default-L240','default-L242') AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');
DELETE FROM savings_accounts WHERE company_id = 'default' AND member_id IN ('default-M141','default-M142') AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');
DELETE FROM members WHERE company_id = 'default' AND id IN ('default-M141','default-M142') AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');

-- Neraca 2025 tetap (isian dan rincian). Isian dana 2025 dari 041 dikembalikan ke angka sheet:
-- tanpa transaksi 2025 tidak ada lagi Dansos/Dekopinda 2025 yang memotong saldo 31 Desember.
SELECT 'default', 'BALANCE_SHEET', '2025:' || item_key, 'UPDATED', json_object('amount', amount),
  json_object('amount', CASE item_key WHEN 'SOCIAL_FUND' THEN 4232995 ELSE 6494387 END),
  'Data script 043_hapus_transaksi_2025'
FROM balance_sheet_items
WHERE company_id = 'default' AND year = 2025
  AND ((item_key = 'SOCIAL_FUND' AND amount = 4547995) OR (item_key = 'PMDK_FUND' AND amount = 8239387))
  AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');
UPDATE balance_sheet_items SET amount = 4232995
WHERE company_id = 'default' AND year = 2025 AND item_key = 'SOCIAL_FUND' AND amount = 4547995 AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');
UPDATE balance_sheet_items SET amount = 6494387
WHERE company_id = 'default' AND year = 2025 AND item_key = 'PMDK_FUND' AND amount = 8239387 AND EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');

-- Kolom 31 Desember 2025 sama dengan NERACA sheet 2025: Kas 71.974.500 (Buku Kas 21.974.442),
-- Piutang Anggota 762.513.237, Piutang Non Anggota 221.390.000, Simpanan Manasuka 232.844.472
-- (dari saldo awal 2026: 762.512.637, 220.606.000, 234.694.090).
CREATE TEMP TABLE sesuai043 (item_key TEXT NOT NULL, amount INTEGER NOT NULL);
DELETE FROM sesuai043 WHERE NOT EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok') OR item_key IN (
  SELECT item_key FROM balance_sheet_items WHERE company_id = 'default' AND year = 2025
);
SELECT 'default', 'BALANCE_SHEET', '2025:' || item_key, 'CREATED', json_object('amount', amount),
  'Data script 043_hapus_transaksi_2025'
FROM sesuai043;
SELECT 'default', 2025, item_key, amount FROM sesuai043;
DROP TABLE sesuai043;


-- Saldo Kas Fisik 31-12-2025 = saldo awal Buku Kas 2026.
SELECT 'default-OPENING-CASH-2026', 'default', '2025-12-31', NULL, 'Koperasi', 'KAS', 'Saldo Kas Fisik Neraca Posisi 31 Desember 2025', 'Masuk', 21974442 WHERE EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');
SELECT 'default', 'default-OPENING-CASH-2026', 'CASH', 'Saldo awal kas', 21974442 WHERE EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');

-- Saldo awal simpanan 2026 per anggota (Pokok, Wajib, Manasuka).

-- Saldo awal pinjaman 2026: pokok, tunggakan (+) atau lebih bayar (-) pokok dan bunga per 31-12-2025.

CREATE TRIGGER components_append_only_delete
BEFORE DELETE ON transaction_components
BEGIN
  SELECT RAISE(ABORT, 'Komponen transaksi tidak dapat dihapus.');
END;

CREATE TRIGGER components_append_only_update
BEFORE UPDATE ON transaction_components
BEGIN
  SELECT RAISE(ABORT, 'Komponen transaksi tidak dapat diubah.');
END;

CREATE TRIGGER transaction_groups_append_only_delete
BEFORE DELETE ON transaction_groups
BEGIN
  SELECT RAISE(ABORT, 'transaction_groups is append-only');
END;

CREATE TRIGGER transaction_groups_append_only_update
BEFORE UPDATE ON transaction_groups
BEGIN
  SELECT RAISE(ABORT, 'transaction_groups is append-only');
END;

CREATE TRIGGER transactions_append_only_delete
BEFORE DELETE ON transactions
BEGIN
  SELECT RAISE(ABORT, 'Transaksi tidak dapat dihapus; buat reversal.');
END;

CREATE TRIGGER transactions_append_only_update
BEFORE UPDATE ON transactions
BEGIN
  SELECT RAISE(ABORT, 'Transaksi tidak dapat diubah; buat reversal.');
END;

SELECT 'default', 'DATA', '2025', 'DELETED', json('{"transaksi": 3664, "komponen": 5722, "pinjaman_saldo_awal": 138, "anggota_saldo_awal": 135, "pinjaman_dihapus": 7, "anggota_dihapus": 2, "kas": 21974442}'), 'Data script 043_hapus_transaksi_2025' WHERE EXISTS (SELECT 1 FROM hapus043_guard WHERE state = 'cocok');
